SELECT 'models' name,COUNT(*) quantity FROM bike_product_model WHERE model_code LIKE #{pattern}
UNION ALL SELECT 'skus',COUNT(*) FROM bike_production_sku WHERE sku_code LIKE #{pattern}
UNION ALL SELECT 'tasks',COUNT(*) FROM bike_production_task WHERE batch_no=#{batch}
UNION ALL SELECT 'vehicles',COUNT(*) FROM bike_vehicle WHERE frame_sn LIKE #{pattern}
UNION ALL SELECT 'parts',COUNT(*) FROM bike_part WHERE batch_no=#{batch}
UNION ALL SELECT 'bindings',COUNT(*) FROM bike_vehicle_part_binding WHERE frame_sn LIKE #{pattern}
UNION ALL SELECT 'stockIn',COUNT(*) FROM bike_stock_in_record WHERE stock_in_no LIKE #{pattern}
UNION ALL SELECT 'stockOut',COUNT(*) FROM bike_stock_out_record WHERE stock_out_no LIKE #{pattern}
UNION ALL SELECT 'orders',COUNT(*) FROM bike_sales_order WHERE order_no LIKE #{pattern}
UNION ALL SELECT 'locks',COUNT(*) FROM bike_inventory_lock WHERE lock_no LIKE #{pattern}
UNION ALL SELECT 'issues',COUNT(*) FROM bike_production_issue WHERE id LIKE #{pattern}
UNION ALL SELECT 'prints',COUNT(*) FROM bike_production_print WHERE id LIKE #{pattern}
UNION ALL SELECT 'scanFailures',COUNT(*) FROM bike_production_scan_failure WHERE task_id LIKE #{pattern}
